box('case','מגדלי העופות (בג"ץ 4885/03, 2004)','נתקף חוק ההסדרים הכלכלי, שהכיל עשרות נושאים נפרדים והובא לאישור מהיר. בית המשפט מתח ביקורת על שיטת החקיקה הזו, המקשה על חברי הכנסת לקיים דיון ענייני, ופסק שיש בה פגם. עם זאת, הוא נמנע מלבטל את החוק, ונתן אזהרה כי המשך השימוש בשיטה זו עלול להצדיק התערבות בעתיד. ההלכה: פגם קיים אך ריסון בפועל.'),
box('case','קוונטינסקי נ׳ הכנסת (2017)','עתירה נגד הליך חקיקה מזורז של חוק בעל השפעה כלכלית. בית המשפט חזר על המבחן של פגם היורד לשורש ההליך, והדגיש שבהליך חקיקה מזורז ובלתי מבוסס יכולה לקרות פגיעה בעקרון ההשתתפות. פרטי הנושא והתוצאה לא אומתו במלואם, ולכן יש להסתמך על ההלכה העקרונית בלבד.'),
h3('7.5 התערבות בהחלטות יו"ר הכנסת ובסדרי הדיון'),
p('בעשורים האחרונים התערב בג"ץ במקרים מסוימים. הדוגמה הבולטת היא בשנת 2020, כשיו"ר הכנסת סירב לקיים הצבעה על בחירת יו"ר חדש: בג"ץ הורה לקיים את ההצבעה, בנימוק שהסירוב פוגע בעקרונות היסוד של המשטר הפרלמנטרי ולא נבע משיקול הדעת הפנימי הרגיל. הדוגמה ממחישה שהאוטונומיה אינה מוחלטת כשמדובר בהליך שמשפיע על כלל מערכת השלטון.'),
box('warn','מלכודות נפוצות',['לטעון שלבית המשפט אין סמכות לבקר את הליך החקיקה - יש, אך מצומצמת.','לבלבל בין ביקורת על תוכן (חוק יסוד) לבין ביקורת על הליך.','להניח שכל פגם בהליך מביא לבטלות - רק פגם היורד לשורש.','לשכוח את ההבדל בין הכרעה על חוקיות (שפיטה) לבין הכרעה על מדיניות.']),
h3('7.6 שלד לפתרון שאלה'),
ol('האם הטענה היא לתוכן החוק או להליך החקיקה?','אם הליך - האם מדובר בעניין פנימי של הכנסת?','החל מבחן שריד: פגיעה בעקרונות היסוד או במרקם החיים הפרלמנטריים.','האם הפגם יורד לשורש ההליך (פגיעה ממשית בהשתתפות)?','בחר סעד: דחייה, אזהרה או בטלות.'),
box('ex','תרגיל פתור','חוק שהכיל עשרות נושאים הובא לאישור במליאה בלילה אחד, וחברי כנסת טענו שלא יכלו לקרוא אותו. <b>פתרון:</b> אין התערבות אוטומטית; יש לבדוק אם הפגם יורד לשורש ההליך. לפי מגדלי העופות, גם כשיש פגם מתחשבים בריסון, ובית המשפט עשוי להסתפק באזהרה.'),
box('key','סיכום הפרק',['שתי רמות: תוכן והליך.','ריסון בענייני פנים; מבחן שריד.','פגם היורד לשורש ההליך - רק אז בטלות.','מגדלי העופות: ביקורת וריסון; התערבות בנסיבות חריגות.'])
