QS=[
Q('מהן שתי הרמות של ביקורת שיפוטית על הכנסת?','תוכן החוק והליך החקיקה',['תוכן החוק ושכר חברי הכנסת','הליך החקיקה ותקציב המדינה','בחירת חברי הכנסת והרכב הממשלה'],'שתי הרמות הן תוכן ההליך. ביקורת על שכר, תקציב או הרכב הממשלה אינה חלק מהבחנה הקלאסית, ולכן הם אינם שתי הרמות.'),
Q('מהו הכלל לגבי התערבות בענייני הפנים של הכנסת?','ריסון: התערבות רק בפגיעה ממשית בעקרונות היסוד',['התערבות מלאה בכל עניין','איסור מוחלט על התערבות','התערבות רק בבחירות'],'ההלכה היא ריסון עם חריגים. התערבות מלאה או איסור מוחלט אינם מתארים את הדין, והבחירות אינן הנושא היחיד.'),
Q('מה קבע מבחן שריד?','התערבות כשיש פגיעה קשה במרקם החיים הפרלמנטריים',['התערבות בכל החלטה של הכנסת','התערבות רק בפסקי דין','התערבות בכל חקיקה'],'שריד מגדיר מבחן מצומצם לפי חומרת הפגיעה. התערבות בכל החלטה אינה המבחן, ופסקי דין וחקיקה אינם תחום המבחן.'),
Q('פגם בהליך החקיקה מוביל לבטלות כאשר:','הוא יורד לשורש ההליך',['הוא כל פגם בנוהל','הוא פגם טכני קל','הוא פגם בפרסום בלבד'],'רק פגם חמור, הפוגע בעקרונות היסוד, מצדיק בטלות. פגם טכני קל או בפרסום בלבד אינו מספיק.'),
Q('מהם שלוש קריאות החקיקה?','קריאה ראשונה, שנייה ושלישית עם ועדה ביניהן',['קריאה בממשלה, בכנסת ובנשיא','קריאה בכנסת בלבד','קריאה בכנסת ובבג"ץ'],'התהליך בכנסת הוא שלוש קריאות. הממשלה, הנשיא ובג"ץ אינם חלק מהקריאות.'),
Q('מגדלי העופות עסק ב:','חוק ההסדרים הכלכלי',['חוק גל','חוק טל','חוק הלאום'],'הפרשה עסקה בביקורת על חקיקת חוק ההסדרים. שאר החוקים נדונו בהקשרים אחרים.'),
Q('מה עשה בית המשפט בפרשת מגדלי העופות?','מתח ביקורת ונמנע מביטול',['ביטל את החוק','אישר בלי הסתייגות','העביר את הנושא לממשלה'],'בית המשפט הזהיר אך לא ביטל. ביטול או אישור מלא אינם מה שנקבע.'),
Q('איזה עקרון נפגע בחוק שאושר בחופזה?','עקרון ההשתתפות של חברי הכנסת',['עקרון השוויון','עקרון חוקיות המנהל','עקרון חופש העיסוק'],'אישור חפוז מונע דיון ענייני. שוויון, חוקיות וחופש העיסוק אינם העיקרון הנפגע.'),
Q('איזה מבין הבאים אינו סוג הצעת חוק?','הצעה של בית המשפט',['ממשלתית','פרטית של ח"כ','של ועדה'],'בית המשפט אינו מציע חוקים. שלושת האחרים הם סוגי הצעות.'),
Q('מה נקבע בבג"ץ ברגמן לעניין הליך?','חוק שלא נתקבל ברוב הנדרש בטל',['חוק שנתקבל ברוב רגיל תקף תמיד','בג"ץ אינו מבקר הליכים','הכנסת רשאית לעקוף שריון'],'ברגמן הוא דוגמה לביקורת על הליך. תקפות ללא תנאי ואי ביקורת הפוכות ממנו.'),
Q('מי רשאי להגיש הצעת חוק פרטית?','חבר כנסת',['שופט','פקיד ממשלתי','נשיא המדינה'],'הצעה פרטית היא של חבר כנסת. שופטים, פקידים והנשיא אינם מציעים חוקים.'),
Q('כשיו"ר הכנסת סירב לקיים הצבעה על בחירת יו"ר חדש (2020):','בג"ץ הורה לקיים את ההצבעה',['בג"ץ התעלם','בג"ץ פיזר את הכנסת','בג"ץ מינה יו"ר'],'בית המשפט התערב והורה לקיים את ההצבעה. פיזור או מינוי אינם בסמכותו.'),
Q('מה משמעות "אוטונומיה פרלמנטרית"?','עצמאות הכנסת בניהול ענייניה הפנימיים',['אי תלות בחוק','אי כפיפות לבג"ץ בכל עניין','סמכות לפסול חוקים'],'היא עצמאות יחסית. אי כפיפות מוחלטת או סמכות פסילה אינן משמעותה.'),
Q('חוק ההסדרים נחשב בעייתי כי:','משלב נושאים רבים ונחקק בחופזה',['הוא חוקק ללא רוב','הוא סותר חוק יסוד בכל סעיף','הוא פוגע בשפיטה'],'הבעיה היא ההליך המקשה על דיון. אין טענה לחוסר רוב או לסתירה בכל סעיף.'),
Q('איזה מבין אלה פגם שיורד לשורש ההליך?','שלילת יכולת ממשית להצביע בצורה מושכלת',['שגיאת כתיב','ניסוח לא אחיד','שינוי סדר הסעיפים'],'פגם היורד לשורש פוגע ביסודות החקיקה. שגיאות כתיב וסדר אינן כאלה.'),
Q('מהי הוראה משוריינת?','הוראה הדורשת רוב מיוחד לשינוי',['הוראה שאינה ניתנת לפרסום','הוראה של שר','הוראה ללא תוקף'],'שריון דורש רוב מוגבר. פרסום או שר אינם מאפיינים.'),
Q('מה הסעד המקובל כשיש פגם קל בהליך?','דחיית העתירה, לעיתים עם אזהרה',['ביטול החוק','פיזור הכנסת','מינוי ועדה'],'פגם קל אינו מצדיק בטלות. ביטול או פיזור הם קיצוניים.'),
Q('מי מציג הצעת חוק ממשלתית?','הממשלה',['בג"ץ','הנשיא','מבקר המדינה'],'הצעה ממשלתית באה מהממשלה. בג"ץ והנשיא אינם מציעים, ומבקר המדינה אינו מוסמך.'),
Q('מתי מתערב בג"ץ בהחלטת ועדה של הכנסת?','כשיש פגיעה חמורה בעקרונות היסוד',['בכל החלטה','לעולם לא','רק בבחירות'],'ההתערבות נעשית לפי חומרה. בכל החלטה או לעולם לא הן הגזמות.'),
Q('איזו קביעה נכונה לגבי פגם בהליך חקיקה?','אינו מוביל אוטומטית לבטלות',['תמיד מוביל לבטלות','אינו שפיט','נבחן רק בידי הכנסת'],'פגם צריך להיות חמור. הטענות האחרות שגויות.'),
]
