SUM[-1:-1]=['<h3>7.7 תפקיד היועץ המשפטי של הכנסת וחזקת התקינות</h3>', '<p>בהליך החקיקה פועל היועץ המשפטי של הכנסת, המייעץ ליו"ר ולוועדות בשאלות של חוקיות ההליך ותוכן ההצעות. עצם העובדה שהכנסת מקיימת בקרה פנימית מחזקת את הנימוק לריסון חיצוני: כשיש מנגנון פנימי, אין סיבה שבית המשפט יחליף אותו. ככלל חלה <b>חזקת תקינות</b> לגבי הליכי חקיקה, והעותר נדרש להוכיח את הפגם. כדי להצליח, העותר צריך להצביע על פגם ממשי, על השפעתו על ההכרעה, ועל כך שלא היה ניתן לתקן אותו בהליך הפנימי. בנוסף, ככל שהעתירה מוגשת מוקדם יותר, בעוד ההליך מתנהל, יש לבית המשפט יותר אפשרות להתערב באופן מתון, כלומר להורות לתקן, מאשר לפסול חוק שנחקק זה מכבר.</p>']
